package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner names a city that already contains the maximum allowed
 * number of owners (50). Carries the offending city so the {@link ExceptionControllerAdvice} can
 * report it to the client, which answers with a 409 Conflict.
 */
public class CityOwnerLimitException extends RuntimeException {

    private final transient String city;

    public CityOwnerLimitException(String city) {
        super("City already at owner capacity: " + city);
        this.city = city;
    }

    public String getCity() {
        return this.city;
    }
}

