91	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
92	
93	    /**
94	     * Process-wide sequence backing the {@code seq} of the structured {@code OWNER_CREATED} event. It
95	     * is incremented once per successful create so each emitted event carries a strictly larger,
96	     * monotonically increasing sequence number than the one before it.
