113	
114	    /**
115	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
116	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
117	     * {@code '@'}) is rejected with a 400 Bad Request.
118	     */
119	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
120	        "mailinator.com",
121	        "tempmail.com",
122	        "guerrillamail.com");
123	
124	    /**
125	     * Required national-number length per E.164 country code. A normalized telephone whose country
126	     * code appears here must carry exactly this many national digits after the code; Australia
127	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
128	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
129	     */
130	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
