221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
224	        String idempotencyKey = currentIdempotencyKey();
225	        OwnerDto replayed = replayIfSeen(idempotencyKey);
226	        if (replayed != null) {
227	            return new ResponseEntity<>(replayed, HttpStatus.OK);
228	        }
229	        validateRequiredFields(ownerFieldsDto);
230	        HttpHeaders headers = new HttpHeaders();
231	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
232	        rejectFutureRegistrationDate(owner.getRegistrationDate());
233	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
234	        owner.setRegistrationDate(registrationDate);
235	        requireDailyCapacity(registrationDate);
236	        requireCityHasCapacity(owner.getCity());
237	        validatePostcode(owner);
238	        applyAddress(owner, ownerFieldsDto);
239	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
240	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
241	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
242	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
243	        requireUniqueIdentity(owner);
244	        flagPossibleDuplicate(owner, declaredHouseholdMember);
245	        owner.setCustomerCode(deduplicateCustomerCode(owner.buildCustomerCode()));
246	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
247	        stampHouseholdSize(owner);
248	        capMembershipLevelToHousehold(owner);
249	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
250	        this.clinicService.saveOwner(owner);
251	        rememberCreate(idempotencyKey, owner);
252	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
253	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
254	            owner.getMembershipNumber());
