607	    /**
608	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
609	     * {@code null}. When present, the value must be a syntactically valid address whose domain is not
610	     * on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); it is then stored and
611	     * returned lower-cased.
612	     *
613	     * @param email the raw email value from the request, possibly {@code null}
614	     * @return the lower-cased email, or {@code null} when none was supplied
615	     * @throws InvalidOwnerFieldsException if a value is present but is not a valid email address or
616	     *     its domain is on the disposable-domain blocklist
617	     */
618	    private String normalizeEmail(String email) {
619	        if (!StringUtils.hasText(email)) {
620	            return null;
621	        }
622	        String trimmed = email.trim();
623	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
624	            throw new InvalidOwnerFieldsException(List.of("email"));
625	        }
626	        String normalized = trimmed.toLowerCase(Locale.ROOT);
627	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
628	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
629	            throw new InvalidOwnerFieldsException(List.of("email"));
630	        }
631	        return normalized;
632	    }
