634	    /**
635	     * Rejects an owner whose whole identity key is already used by an existing (non-deleted) owner.
636	     * This is the single consolidated duplicate check: the identity key
637	     * ({@link Owner#getIdentityKey()}) is the lower-case SHA-256 hex of the owner's normalized
638	     * telephone, lower-cased email (empty when absent) and the Soundex of its last name joined with
639	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
640	     * owner's. Because the telephone is part of the key, two owners sharing a last name and postcode
641	     * but carrying different telephones have different identity keys and are both allowed (the second
642	     * is flagged a soft match by {@link #flagPossibleDuplicate}). Owners flagged deleted are ignored.
643	     *
644	     * @param owner the owner being created, with its normalized telephone, email and last name set
645	     * @throws DuplicateIdentityException if another owner already has this identity key
646	     */
647	    private void requireUniqueIdentity(Owner owner) {
648	        String identityKey = owner.getIdentityKey();
649	        boolean inUse = this.clinicService.findAllOwners().stream()
650	            .filter(existing -> !existing.isDeleted())
651	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
652	        if (inUse) {
653	            throw new DuplicateIdentityException(identityKey);
654	        }
