657	    /**
658	     * De-duplicates a newly computed customer code against the codes already held by existing owners.
659	     * When the computed code is unique it is returned unchanged. When it collides with an existing
660	     * owner's {@code customerCode}, {@code '-<n>'} is appended with the smallest {@code n} of 2 or more
661	     * that makes the result unique (so a second collision yields {@code '-2'}, a third {@code '-3'}, and
662	     * so on), and that de-duplicated code is returned.
663	     *
664	     * @param customerCode the freshly computed customer code to de-duplicate
665	     * @return a customer code not held by any existing owner
666	     */
667	    private String deduplicateCustomerCode(String customerCode) {
668	        Set<String> inUse = this.clinicService.findAllOwners().stream()
669	            .map(Owner::getCustomerCode)
670	            .filter(Objects::nonNull)
671	            .collect(Collectors.toSet());
672	        if (!inUse.contains(customerCode)) {
673	            return customerCode;
674	        }
675	        int n = 2;
676	        String candidate;
677	        do {
678	            candidate = customerCode + "-" + n;
679	            n++;
680	        } while (inUse.contains(candidate));
681	        return candidate;
682	    }
