684	    /**
685	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
686	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
687	     * but it shares an existing owner's last-name {@linkplain Soundex#encode(String) Soundex} and postcode
688	     * (both present and equal) while carrying a different identity key. When such an existing owner is
689	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
690	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
691	     * is false and {@code possibleDuplicateOf} is left unset.
692	     *
693	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
694	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
695	     *
696	     * @param owner the owner being created, with its normalized telephone, email, last name and postcode set
697	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
698	     */
699	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
700	        if (declaredHouseholdMember || owner.getPostcode() == null) {
701	            owner.setPossibleDuplicate(false);
702	            return;
703	        }
704	        String identityKey = owner.getIdentityKey();
705	        String soundex = Soundex.encode(owner.getLastName());
706	        Integer matchId = this.clinicService.findAllOwners().stream()
707	            .filter(existing -> soundex.equals(Soundex.encode(existing.getLastName()))
708	                && owner.getPostcode().equals(existing.getPostcode())
709	                && !identityKey.equals(existing.getIdentityKey()))
710	            .map(Owner::getId)
711	            .min(Integer::compareTo)
712	            .orElse(null);
713	        owner.setPossibleDuplicate(matchId != null);
714	        owner.setPossibleDuplicateOf(matchId);
715	    }
