783	     * @param lastName the last name of the household
784	     * @param postcode the postcode of the household, possibly {@code null}
785	     * @return the 12-character upper-case hex household identifier
786	     */
787	    private String computeHouseholdId(String lastName, String postcode) {
788	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
789	        try {
790	            byte[] digest = MessageDigest.getInstance("SHA-256")
791	                .digest(key.getBytes(StandardCharsets.UTF_8));
792	            StringBuilder hex = new StringBuilder(12);
793	            for (int i = 0; i < 6; i++) {
794	                hex.append(String.format("%02X", digest[i]));
795	            }
796	            return hex.toString();
797	        } catch (NoSuchAlgorithmException e) {
798	            throw new IllegalStateException("SHA-256 algorithm not available", e);
799	        }
800	    }
801	
802	    /**
803	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
804	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
805	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
806	     *
807	     * @param value the raw value, possibly {@code null}
808	     * @return the normalized value
809	     */
810	    private String normalizeForHousehold(String value) {
811	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
812	    }
813	
814	    /**
815	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
816	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
817	     * value yields an empty string.
818	     *
819	     * @param value the raw value, possibly {@code null}
820	     * @return the trimmed, whitespace-collapsed value
821	     */
822	    private String collapseWhitespace(String value) {
823	        if (value == null) {
824	            return "";
825	        }
826	        return value.trim().replaceAll("\\s+", " ");
827	    }
828	
829	    /**
830	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
831	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
832	     * is upper-cased, and common street-type abbreviations are expanded as whole words
833	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
834	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
835	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
836	     *
837	     * @param address the raw address value, possibly {@code null}
838	     * @return the normalized address
839	     */
840	    private String normalizeAddress(String address) {
841	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
842	        if (collapsed.isEmpty()) {
843	            return "";
844	        }
845	        String[] tokens = collapsed.split(" ");
846	        StringBuilder normalized = new StringBuilder();
847	        for (int i = 0; i < tokens.length; i++) {
848	            if (i > 0) {
849	                normalized.append(' ');
850	            }
851	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
852	        }
853	        return normalized.toString();
854	    }
855	
856	    /**
857	     * Applies the owner's address from the request, preferring the structured form over the flat one.
858	     * When a non-blank {@code addressLine1} is supplied it is normalized ({@link #normalizeAddress}) and
859	     * stored, along with the normalized {@code addressLine2} when present, and the stored {@code address}
860	     * is the composed string ({@link #composeAddress}). Otherwise the flat {@code address} input is
861	     * normalized and stored, and the structured lines are cleared. Normalization therefore applies to
862	     * whichever address fields are supplied, and everything that reads {@link Owner#getAddress()} sees
863	     * the structured address when present, falling back to the flat address.
864	     *
865	     * @param owner the owner being created
866	     * @param ownerFieldsDto the submitted owner fields
867	     */
868	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
869	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
870	        if (StringUtils.hasText(line1)) {
871	            String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
872	            String normalizedLine2 = StringUtils.hasText(line2) ? line2 : null;
873	            owner.setAddressLine1(line1);
874	            owner.setAddressLine2(normalizedLine2);
875	            owner.setAddress(composeAddress(line1, normalizedLine2));
876	        } else {
877	            owner.setAddressLine1(null);
878	            owner.setAddressLine2(null);
879	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
880	        }
881	    }
882	
883	    /**
884	     * Composes the stored-and-returned {@code address} string from the normalized structured lines: the
885	     * normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
886	     * appended when the second line is present.
887	     *
888	     * @param line1 the normalized first address line
889	     * @param line2 the normalized second address line, or {@code null} when absent
890	     * @return the composed address string
891	     */
892	    private String composeAddress(String line1, String line2) {
893	        return line2 == null ? line1 : line1 + " " + line2;
894	    }
895	
896	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
897	    @Override
898	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
899	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
900	        if (currentOwner == null) {
901	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
902	        }
903	        currentOwner.setAddress(ownerFieldsDto.getAddress());
904	        currentOwner.setCity(ownerFieldsDto.getCity());
905	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
906	        currentOwner.setLastName(ownerFieldsDto.getLastName());
907	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
908	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
909	        this.clinicService.saveOwner(currentOwner);
910	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
911	    }
912	
913	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
914	    @Transactional
915	    @Override
916	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
917	        Owner owner = this.clinicService.findOwnerById(ownerId);
918	        if (owner == null) {
919	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
920	        }
921	        owner.setDeleted(true);
922	        this.clinicService.saveOwner(owner);
923	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
924	    }
925	
926	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
927	    @Override
928	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
929	        Owner owner = this.clinicService.findOwnerById(ownerId);
930	        if (owner == null) {
931	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
932	        }
933	        HttpHeaders headers = new HttpHeaders();
934	        Pet pet = petMapper.toPet(petFieldsDto);
935	        owner.setId(ownerId);
936	        pet.setOwner(owner);
937	        pet.getType().setName(null);
938	        this.clinicService.savePet(pet);
939	        PetDto petDto = petMapper.toPetDto(pet);
940	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
941	            .buildAndExpand(pet.getId()).toUri());
942	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
943	    }
944	
945	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
946	    @Override
947	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
948	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
949	        if (currentOwner != null) {
950	            Pet currentPet = this.clinicService.findPetById(petId);
951	            if (currentPet != null) {
952	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
953	                currentPet.setName(petFieldsDto.getName());
954	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
955	                this.clinicService.savePet(currentPet);
956	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
957	            }
958	        }
959	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
960	    }
961	
962	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
963	    @Override
964	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
965	        HttpHeaders headers = new HttpHeaders();
966	        Visit visit = visitMapper.toVisit(visitFieldsDto);
967	        Pet pet = new Pet();
968	        pet.setId(petId);
969	        visit.setPet(pet);
970	        this.clinicService.saveVisit(visit);
971	        VisitDto visitDto = visitMapper.toVisitDto(visit);
972	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
973	            .buildAndExpand(visit.getId()).toUri());
974	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
975	    }
976	
977	
978	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
979	    @Override
980	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
981	        Owner owner = this.clinicService.findOwnerById(ownerId);
982	        if (owner != null) {
983	            Pet pet = owner.getPet(petId);
984	            if (pet != null) {
985	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
986	            }
987	        }
988	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
989	    }
990	}
